KG42.register("clusters-a31ce7fb0f0730c8f287b6f3",{"id":"21-dso_flexibility_optimization::v142-d-CL001","paper":"21-dso_flexibility_optimization","label":"Participation mode of flexibility providers and admission conditions for household-level controllers","record":{"cluster_id":"v142-d-CL001","label":"Participation mode of flexibility providers and admission conditions for household-level controllers","market_meaning":"Prosumers may form a community to participate in the local flexibility market; participating households must be equipped with an LC capable of receiving and executing SESP instructions. The general admission statement and the prosumer participation statement together define the participation mode and technical prerequisites.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"The two chains belong to the same market and participation stage. R001 covers prosumers, DER, and energy communities, while R005 supplements how prosumers form communities and restates their LC conditions; the subject scope is retained, and community grouping is not interpreted as a mandatory requirement.","assembly_status":"assembled","boundary_rationale":"With the admission obligation borne by participants as the boundary, the general condition and the subject participation mode are combined; the LC obligation within the overlapping scope is counted only once. Resource dispatch and post-activation payment have different decisions and outcomes and are assembled separately.","chain_bindings":[{"chain_id":"v141-c-R001","ownership":"primary","role":"core","rationale":"Provide the general household-level control capability prerequisite for participating in the market."},{"chain_id":"v141-c-R005","ownership":"primary","role":"core","rationale":"Supplement the prosumer and community participation mode, and retain the subject-side formulation of the LC obligation, without counting the restatement as another independent obligation."}],"connections":[{"connection_id":"v142-d-CL001-CN01","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R005","kind":"complementary_scope","from_refs":["v141-c-R001::phi::v141-c-R001-C001"],"to_refs":["v141-c-R005::phi::v141-c-R005-C001","v141-c-R005::phi::v141-c-R005-C002"],"evidence_ids":["v141-b-g01-ev-012","v141-b-g02-ev40"],"rationale":"The given paragraph explains both the community participation mode and the LC prerequisite for participating households, supporting the complementarity of the general admission perspective and the prosumer participation perspective; on this basis, no dependency that community grouping must precede admission is added."}],"object_mappings":[{"mapping_id":"v142-d-CL001-OM01","kind":"alternative_representation","member_refs":["v141-c-R001::phi::v141-c-R001-C001","v141-c-R005::phi::v141-c-R005-C002"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-012","v141-b-g02-ev40"],"rationale":"The two items are the general formulation and the prosumer-side formulation of the same LC participation prerequisite, with different subject scopes and functional attributions; the association shows their overlapping content and neither unconditionally equates the two nor deletes either original item."}],"gaps":[{"gap_id":"v142-d-CL001-G01","category":"unverified_source","description":"The B evidence used remains unverified and has only candidate-support eligibility for this experiment; assembled only indicates that this procedural candidate can be assembled within the disclosed scope.","chain_ids":["v141-c-R001","v141-c-R005"],"object_refs":["v141-c-R001::phi::v141-c-R001-C001","v141-c-R005::phi::v141-c-R005-C001","v141-c-R005::phi::v141-c-R005-C002"],"evidence_ids":["v141-b-g01-ev-012","v141-b-g02-ev40"],"proposal_ids":[],"required_work":"Manual review shall check the sources and the applicable scope of subjects and inspect the two frozen chains; candidate status must not be interpreted as passing an independent source audit."},{"gap_id":"v142-d-CL001-G02","category":"ontology_extension","description":"LC does not yet have an approved independent object; admission.local_area here carries the technical admission condition, and geographical eligibility cannot be additionally inferred from the node name, nor can LC be equated with a central coordinator.","chain_ids":["v141-c-R001","v141-c-R005"],"object_refs":["v141-c-R001::V::admission.local_area","v141-c-R005::V::participation.prosumer"],"evidence_ids":["v141-b-g01-ev-012","v141-b-g01-ev-017"],"proposal_ids":["proposal:v141-b-g01-local-controller"],"required_work":"Manual review shall evaluate the pending LC proposal and the carrying scope of existing nodes; this time only references are retained, and no graph objects are added."}]},"rule_refs":["21-dso_flexibility_optimization::v141-c-R001","21-dso_flexibility_optimization::v141-c-R005"],"unresolved_rule_refs":[],"node_ids":["COMP-7b77631c556e010b","COMP-91014469e963dafb"]});
